
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_mn15_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_mn15", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([1.263508402156544e+00, 1.061719206838739e+00, 7.883229245000336e-01, 4.292084901841449e-01, -1.910881349515873e-02, -5.309405906195579e-01, -1.021236941182440e+00, -1.327506771625504e+00, -1.324221403425649e+00, -1.258698004990310e+00, -1.186833311282828e+00, -5.530673609318444e-01, -3.008292232631437e-01, -2.676399616721022e-01, -2.543097357113203e-01, -2.140831569966994e-01, -7.121995460826198e-02, 1.699087958336275e-02, 8.420673596467669e-03, 1.062794838374377e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


